<script setup lang="ts">
import { computed } from 'vue'
import { roundLabel,loopTime,sourceLabel } from '../utils/learningLoop'
const props=defineProps<{rounds:any[]}>(),emit=defineEmits<{open:[any]}>()
const rows=computed(()=>[...(props.rounds||[])].sort((a,b)=>b.round-a.round))
</script>
<template><div class="retest-round-list"><article v-for="row in rows" :key="row.cycle_id||row.round" class="round-result-card"><header><b>第 {{ row.round }} 轮</b><span :class="{passed:row.status==='passed'}">{{ roundLabel(row) }}</span></header><div class="round-score"><strong>{{ row.result_determinable?`${row.score ?? row.correct_count} / ${row.max_score ?? row.question_count}`:'—' }}<small v-if="row.result_determinable">{{ row.max_score!=null?'分':'题' }}</small></strong><span>{{ row.result_determinable?`答对 ${row.correct_count}/${row.question_count} 题`:`共 ${row.question_count} 题` }}</span></div><div class="round-concepts"><span v-for="name in row.concept_names" :key="name">{{ name }}</span></div><footer><div><time>{{ loopTime(row.completed_at||row.submitted_at||row.published_at) }}</time><span>{{ sourceLabel(row.source_counts) }}</span></div><el-button v-if="row.release_id||row.attempt_id||row.retest_attempt_id" @click="emit('open',row)">{{ row.submitted_at?'查看答卷':'继续作答' }}</el-button></footer></article><el-empty v-if="!rows.length" description="尚无复测记录" /></div></template>
